import '../auth_repository.dart';class LoginUseCase{LoginUseCase(this.repo);final AuthRepository repo;call(String p,String pw)=>repo.login(p,pw);}class RegisterUseCase{RegisterUseCase(this.repo);final AuthRepository repo;call({required String name,required String phone,String? email,required String password})=>repo.register(name:name,phone:phone,email:email,password:password);}class VerifyUseCase{VerifyUseCase(this.repo);final AuthRepository repo;call(String p,String o)=>repo.verify(p,o);}
